//! API reference page, walked from the generated `OpenAPI` document.

use std::fmt::Write as _;

use anyhow::{Result, anyhow};
use serde_json::Value;

const METHODS: [&str; 5] = ["get", "post", "put", "patch", "delete"];

/// Markdown for `reference/api.md`.
pub fn render(spec: &Value) -> Result<String> {
    let mut out = String::new();
    let info = &spec["info"];
    let _ = write!(
        out,
        "<!-- Generated by `cargo xtask docs` from the OpenAPI document that \
         helia-server builds (reference/openapi.json). Do not edit. -->\n\n\
         # API reference\n\n\
         {} Version {} of the document; licence {}.\n\n\
         The narrative guide, with examples and the security model, is in \
         [The API](../user-guide/api.md). The machine-readable document is \
         [openapi.json](openapi.json), and a running server serves it at \
         `/api/v1/openapi.json`.\n\n\
         All paths below are relative to `/api/v1`.\n\n",
        text(&info["description"]),
        text(&info["version"]),
        text(&info["license"]["name"]),
    );

    out.push_str("## Operations\n\n");
    let paths = spec["paths"]
        .as_object()
        .ok_or_else(|| anyhow!("document has no paths"))?;
    let mut keys: Vec<&String> = paths.keys().collect();
    keys.sort();
    for path in keys {
        let item = &paths[path];
        for m in METHODS {
            if let Some(op) = item.get(m) {
                operation(&mut out, &short_path(path), m, op, spec);
            }
        }
    }

    out.push_str("## Schemas\n\n");
    if let Some(schemas) = spec["components"]["schemas"].as_object() {
        let mut names: Vec<&String> = schemas.keys().collect();
        names.sort();
        for n in names {
            schema(&mut out, n, &schemas[n]);
        }
    }
    Ok(out)
}

/// Paths are served under `/api/v1`; show them without the prefix.
fn short_path(p: &str) -> String {
    p.strip_prefix("/api/v1").unwrap_or(p).to_owned()
}

fn text(v: &Value) -> String {
    v.as_str().unwrap_or_default().trim().to_owned()
}

fn cell(s: &str) -> String {
    s.trim().replace('|', "\\|").replace('\n', " ")
}

fn operation(out: &mut String, path: &str, method: &str, op: &Value, spec: &Value) {
    let _ = writeln!(out, "### `{} {path}`\n", method.to_uppercase());
    let summary = text(&op["summary"]);
    if !summary.is_empty() {
        let _ = writeln!(out, "**{summary}**\n");
    }
    let desc = text(&op["description"]);
    if !desc.is_empty() && desc != summary {
        let _ = writeln!(out, "{desc}\n");
    }
    let open = op
        .get("security")
        .and_then(Value::as_array)
        .is_some_and(|s| {
            s.iter()
                .any(|e| e.as_object().is_some_and(serde_json::Map::is_empty))
        });
    if open {
        out.push_str("Needs no token.\n\n");
    }

    if let Some(params) = op["parameters"].as_array().filter(|p| !p.is_empty()) {
        out.push_str("| Parameter | In | Type | Required | Description |\n|---|---|---|---|---|\n");
        for p in params {
            let p = deref(p, spec);
            let _ = writeln!(
                out,
                "| `{}` | {} | {} | {} | {} |",
                text(&p["name"]),
                text(&p["in"]),
                type_str(&p["schema"]),
                if p["required"].as_bool().unwrap_or(false) {
                    "yes"
                } else {
                    "no"
                },
                cell(&text(&p["description"])),
            );
        }
        out.push('\n');
    }

    if let Some(body) = op.get("requestBody") {
        let body = deref(body, spec);
        out.push_str("Request body:\n\n");
        content(out, &body["content"]);
        out.push('\n');
    }

    if let Some(responses) = op["responses"].as_object() {
        out.push_str("| Status | Meaning | Body |\n|---|---|---|\n");
        let mut codes: Vec<&String> = responses.keys().collect();
        codes.sort();
        for c in codes {
            let r = deref(&responses[c], spec);
            let mut body = Vec::new();
            if let Some(content) = r["content"].as_object() {
                for (mime, v) in content {
                    let t = v.get("schema").map_or_else(String::new, type_str);
                    body.push(if t.is_empty() {
                        format!("`{mime}`")
                    } else {
                        format!("`{mime}`: {t}")
                    });
                }
            }
            let mut meaning = cell(&text(&r["description"]));
            if meaning.is_empty() {
                reason(c).clone_into(&mut meaning);
            }
            let _ = writeln!(out, "| {c} | {meaning} | {} |", body.join("; "));
        }
        out.push('\n');
    }
}

/// Standard reason phrase, for responses the document leaves undescribed.
fn reason(code: &str) -> &'static str {
    match code {
        "200" => "OK",
        "202" => "Accepted",
        "204" => "No content",
        "404" => "Not found",
        "409" => "Conflict",
        "429" => "Too many requests",
        _ => "",
    }
}

fn content(out: &mut String, c: &Value) {
    if let Some(map) = c.as_object() {
        for (mime, v) in map {
            let t = v.get("schema").map_or_else(String::new, type_str);
            let _ = writeln!(out, "* `{mime}`: {t}");
        }
    }
}

fn deref(v: &Value, spec: &Value) -> Value {
    if let Some(r) = v.get("$ref").and_then(Value::as_str) {
        let mut cur = spec;
        for part in r.trim_start_matches("#/").split('/') {
            cur = &cur[part];
        }
        return cur.clone();
    }
    v.clone()
}

/// Human description of a JSON schema, linking named schemas.
fn type_str(s: &Value) -> String {
    if let Some(r) = s.get("$ref").and_then(Value::as_str) {
        let name = r.rsplit('/').next().unwrap_or(r);
        return format!("[{name}](#{})", name.to_lowercase());
    }
    for key in ["oneOf", "anyOf", "allOf"] {
        if let Some(list) = s.get(key).and_then(Value::as_array) {
            let parts: Vec<String> = list
                .iter()
                .filter(|v| v["type"] != "null")
                .map(type_str)
                .collect();
            let nullable = list.iter().any(|v| v["type"] == "null");
            return format!(
                "{}{}",
                parts.join(" or "),
                if nullable { " or null" } else { "" }
            );
        }
    }
    let mut types: Vec<String> = match &s["type"] {
        Value::String(t) => vec![t.clone()],
        Value::Array(a) => a
            .iter()
            .filter_map(|v| v.as_str().map(str::to_owned))
            .collect(),
        _ => Vec::new(),
    };
    let nullable = types.iter().any(|t| t == "null");
    types.retain(|t| t != "null");
    let mut base = types.join(" or ");
    if let Some(items) = s.get("items") {
        base = format!("array of {}", type_str(items));
    }
    if let Some(f) = s.get("format").and_then(Value::as_str) {
        let _ = write!(base, " ({f})");
    }
    if let Some(values) = s.get("enum").and_then(Value::as_array) {
        let list: Vec<String> = values
            .iter()
            .filter(|v| !v.is_null())
            .map(|v| {
                format!(
                    "`{}`",
                    v.as_str().map_or_else(|| v.to_string(), str::to_owned)
                )
            })
            .collect();
        base = format!("{base}, one of {}", list.join(", "));
    }
    if let (Some(min), Some(max)) = (s.get("minimum"), s.get("maximum")) {
        let _ = write!(base, ", {min} to {max}");
    }
    if nullable {
        base.push_str(", may be null");
    }
    base
}

fn schema(out: &mut String, name: &str, s: &Value) {
    let _ = writeln!(out, "### {name}\n");
    let d = text(&s["description"]);
    if !d.is_empty() {
        let _ = writeln!(out, "{d}\n");
    }
    if let Some(values) = s.get("enum").and_then(Value::as_array) {
        let list: Vec<String> = values
            .iter()
            .map(|v| format!("`{}`", v.as_str().unwrap_or_default()))
            .collect();
        let _ = writeln!(out, "One of {}.\n", list.join(", "));
    }
    if let Some(variants) = s.get("oneOf").and_then(Value::as_array) {
        out.push_str("One of:\n\n");
        for v in variants {
            let d = text(&v["description"]);
            let mut fields: Vec<String> = v["properties"].as_object().map_or_else(Vec::new, |p| {
                p.iter()
                    .map(
                        |(k, val)| match val.get("const").or_else(|| val["enum"].get(0)) {
                            Some(c) => format!("`{k}` = `{}`", c.as_str().unwrap_or_default()),
                            None => format!("`{k}` ({})", type_str(val)),
                        },
                    )
                    .collect()
            });
            fields.sort();
            let _ = writeln!(out, "* {d} Fields: {}.", fields.join(", "));
        }
        out.push('\n');
    }
    if let Some(props) = s["properties"].as_object() {
        let required: Vec<&str> = s["required"]
            .as_array()
            .map(|r| r.iter().filter_map(Value::as_str).collect())
            .unwrap_or_default();
        out.push_str("| Field | Type | Required | Description |\n|---|---|---|---|\n");
        let mut keys: Vec<&String> = props.keys().collect();
        keys.sort();
        for k in keys {
            let p = &props[k];
            let default = p
                .get("default")
                .filter(|d| !d.is_null())
                .map(|d| format!(" Default `{d}`."))
                .unwrap_or_default();
            let _ = writeln!(
                out,
                "| `{k}` | {} | {} | {}{default} |",
                type_str(p),
                if required.contains(&k.as_str()) {
                    "yes"
                } else {
                    "no"
                },
                cell(&text(&p["description"])),
            );
        }
        out.push('\n');
    }
}
